# ABOUTME: Semantic action for UseStatement - categorizes use statements and builds UseStatement IR nodes
# ABOUTME: UseStatement handles version checks, pragmas, modules, and external modules

use 5.42.0;
use experimental 'class';
use Chalk::Grammar;

# Known pragmas that are no-ops for Chalk (Chalk provides these by default)
my %NO_OP_PRAGMAS;
$NO_OP_PRAGMAS{'strict'} = 1;
$NO_OP_PRAGMAS{'warnings'} = 1;
$NO_OP_PRAGMAS{'utf8'} = 1;
$NO_OP_PRAGMAS{'experimental'} = 1;
$NO_OP_PRAGMAS{'feature'} = 1;

# Known external modules (not Chalk::* modules)
my %EXTERNAL_MODULES;
$EXTERNAL_MODULES{'builtin'} = 1;
$EXTERNAL_MODULES{'Carp'} = 1;
$EXTERNAL_MODULES{'Data::Dumper'} = 1;
$EXTERNAL_MODULES{'Scalar::Util'} = 1;
$EXTERNAL_MODULES{'List::Util'} = 1;
$EXTERNAL_MODULES{'Test::More'} = 1;
$EXTERNAL_MODULES{'Test::Deep'} = 1;

# Categorize use statement into: version, pragma, module, or external
sub _categorize_use_statement($module_name) {
    # Version check: use 5.42.0;
    return 'version' if $module_name =~ /^\d+\.\d+/;

    # Pragma: use experimental qw(...);
    return 'pragma' if exists $NO_OP_PRAGMAS{$module_name};

    # Chalk module: use Chalk::IR::Node;
    return 'module' if $module_name =~ /^Chalk::/;

    # External module: use builtin qw(...);
    return 'external' if exists $EXTERNAL_MODULES{$module_name};

    # Default to external for unknown modules
    return 'external';
}

# Extract import list from QuotedWordList child
# QuotedWordList is qw(...) or qw/.../
sub _extract_imports($context, $start_index) {
    my @imports = ();

    # Look for QuotedWordList child after the module name
    for my $i ($start_index..$context->children->$#*) {
        my $child = $context->child($i);
        next unless defined $child;

        # Check if this is a QuotedWordList
        if (ref($child) eq 'ARRAY') {
            # QuotedWordList semantic value is array ref of import names
            @imports = $child->@*;
            last;
        }
